const UNIT=Object.fromEntries(UNITS.map(u=>[u.id,u]));
const GAME_UNIT={};UNITS.forEach(u=>u.games.forEach(g=>{if(!GAME_UNIT[g[0]])GAME_UNIT[g[0]]=u.id;}));
const unitOf=g=>GAME_UNIT[g]||(String(g).includes('-')?String(g).split('-')[1]:null);
function curUnit(){if(typeof zQU!=='undefined'&&zQU)return zQU;const g=zCur;if(typeof lastUnit!=='undefined'&&lastUnit&&UNIT[lastUnit]&&UNIT[lastUnit].games.some(x=>x[0]===g))return lastUnit;return unitOf(g);}
function sLog(ok,hint){const u=curUnit();if(!u||!UNIT[u])return;const d=dkey();const L=zSave.log[d]=zSave.log[d]||{};const a=L[u]=L[u]||[0,0,0];if(hint)a[2]++;else a[ok?0:1]++;zPut();}
function zMiss(){try{sLog(false);}catch(e){}}
const zPriorGain2=slGain;slGain=function(n=1){zPriorGain2(n);try{sLog(true);}catch(e){}};
function stats(u,from=0,to=7){let ok=0,miss=0,hint=0;for(let i=from;i<to;i++){const d=new Date();d.setDate(d.getDate()-i);const a=(zSave.log[dkey(d)]||{})[u];if(a){ok+=a[0];miss+=a[1];hint+=a[2];}}return {ok,miss,hint,n:ok+miss,acc:ok+miss?ok/(ok+miss):null};}
function easy(u){if(!u)return false;const s=stats(u,0,14);if(s.n>=4)return s.acc<.6;const c=zSave.check&&zSave.check.scores;return !!(c&&c[u]===0);}
function unitScore(u){const s=stats(u,0,14);const c=zSave.check&&zSave.check.scores?zSave.check.scores[u]:null;return (s.acc==null?.5:s.acc)+(c==null?.5:c)*.6;}
function hintBtn(host,getRight){if(!host||host.querySelector('.z-hint'))return;const b=document.createElement('button');b.className='z-hint';b.type='button';b.textContent='💡 Hint';host.appendChild(b);b.onclick=()=>{const r=getRight();if(!r)return;r.classList.remove('z-glow');void r.offsetWidth;r.classList.add('z-glow');sLog(false,true);b.disabled=true;audio('tap');};}
const trimOpts=(opts,isRight)=>{if(!easy(curUnit()))return opts;const r=opts.filter(isRight),w=opts.filter(o=>!isRight(o));return zShuf([...r.slice(0,1),...w.slice(0,1)]);};
function slThink(side,text){const a=$id('sl'+side);if(!a)return;let t=a.querySelector('.sl-thought');if(!t){t=document.createElement('div');t.className='sl-thought';a.appendChild(t);}t.textContent='💭 '+text;t.classList.remove('on');void t.offsetWidth;t.classList.add('on');}
function slUnthink(){document.querySelectorAll('.sl-thought').forEach(t=>t.remove());}
const speakTone=(text,who,pitch,rate)=>{try{if(window.RikiVoice)return RikiVoice.speak(text,{character:who==='friend'?'maya':who==='friend2'?'zoe':who,pitch,rate});}catch(e){}return slSpeak(text,who);};

