function drawWatch(uid){const u=UNIT[uid],e=EP[uid];zCur='watch-'+uid;slWho={A:e.l,B:e.r};
 const t=zShell(`🎬 Watch: ${u.name}`,`<div class="w-tag" id="wTag">🎬 Episode</div>${slSceneHTML(e.l,e.r)}<div class="sl-choices" id="slCh" hidden></div><p class="sl-note" id="slNote" hidden></p>`);
 const play=async lines=>{for(const [s,txt,ex,th] of lines){if(!zLive(t))return false;slHush(s==='A'?'B':'A');await slSay(s,txt,ex);if(th){slThink(s,th);await slWait(1900);}await slWait(250);}return zLive(t);};
 const tag=(txt,cls)=>{const g=$id('wTag');if(g){g.textContent=txt;g.className='w-tag '+(cls||'');}};
 (async()=>{await slWait(300);if(!await play(e.setup))return;tag('😬 Oops version','oops');if(!await play(e.bad))return;await slWait(500);
  tag('⏪ Rewind…','rew');slHush('A');slHush('B');slUnthink();slExpr('A','neutral');slExpr('B','neutral');$id('slScene').classList.add('rewind');await slWait(1300);if(!zLive(t))return;$id('slScene').classList.remove('rewind');
  tag('✨ Super version','super');if(!await play(e.setup))return;if(!await play(e.good))return;slFx(['💖','✨','⭐'],10);await slWait(700);if(!zLive(t))return;
  tag('🤔 Your turn');const ch=$id('slCh');ch.hidden=false;ch.innerHTML=`<p class="zg-ask">${e.q}</p><button class="sl-choice c0" data-v="0">😬 The oops version</button><button class="sl-choice c1" data-v="1">✨ The super version</button><button class="sl-choice c2" data-r="1">🔁 Watch again</button>`;if(window.RikiFit)RikiFit();
  ch.querySelector('[data-r]').onclick=()=>drawWatch(uid);
  ch.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{if(b.dataset.v==='1'){audio('good');slGain(1);(zSave.done[uid]=zSave.done[uid]||{}).watch=1;zPut();ch.querySelectorAll('button').forEach(x=>x.disabled=true);(async()=>{ch.innerHTML=`<div class="w-steps"><b>✨ Riki’s ${u.name} trick</b>${u.steps.map((s,i)=>`<span data-s="${i}">${s[0]} ${s[1]}</span>`).join('')}</div>`;slHush('B');for(let i=0;i<u.steps.length;i++){if(!zLive(t))return;const el=ch.querySelector(`[data-s="${i}"]`);if(el)el.classList.add('on');await slSay('A',u.steps[i][1]+'.',i===u.steps.length-1?'excited':'happy');}if(zLive(t))zDone(t,'🎬 Great watching! Now try a game.',()=>drawWatch(uid),2);const ag=$id('zAgain');if(ag){ag.textContent='🎮 Back to games';ag.onclick=()=>{audio('tap');newHub();};}})();}else{audio('tap');zMiss();zNote('Hmm. Look at how the other person felt in their thought bubble.');}});})();}

/* Steps: put the skill steps in order while the doll acts them */
function drawSteps(uid){const u=UNIT[uid];zCur='steps-'+uid;slWho={A:'riki',B:EP[uid].r};const cards=zShuf(u.steps.map((s,i)=>[...s,i]));let at=0,miss=0;
 const t=zShell(`🪜 Steps: ${u.name}`,`${slSceneHTML('riki',EP[uid].r)}<ol class="st-ladder" id="stL">${u.steps.map((_,i)=>`<li data-n="${i}"><span>${i+1}</span></li>`).join('')}</ol><div class="zr-cards" id="stC">${cards.map(c=>`<button class="zr-card" data-i="${c[2]}">${c[0]} ${c[1]}</button>`).join('')}</div><p class="sl-note" id="slNote">What comes first? Tap the steps in order.</p>`);
 if(easy(uid))hintBtn($id('zRoot'),()=>document.querySelector(`#stC [data-i="${at}"]`));
 document.querySelectorAll('#stC [data-i]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;const i=+b.dataset.i;
  if(i===at){b.disabled=true;b.classList.add('ok');const li=document.querySelector(`#stL [data-n="${i}"]`);li.innerHTML=`<span>✓</span>${u.steps[i][0]} ${u.steps[i][1]}`;li.classList.add('on');at++;audio('good');zNote(at<u.steps.length?'Yes! What comes next?':'');slHush('A');slSay('A',u.steps[i][1]+'!',at===u.steps.length?'excited':'happy');
   if(at===u.steps.length){slGain(1);(zSave.done[uid]=zSave.done[uid]||{}).steps=1;zPut();slExpr('B','excited','bounce');slFx(['🪜','⭐','✨'],10);await slWait(1600);zDone(t,miss?'🪜 You know the steps! Now practice them.':'🪜 Perfect order! Now practice them.',null,2);const ag=$id('zAgain');if(ag){ag.textContent='▶ Practice games';ag.onclick=()=>{audio('tap');drawUnit(uid);};}}}
  else{miss++;zMiss();audio('tap');b.classList.remove('no');void b.offsetWidth;b.classList.add('no');zNote('Not yet! Which step has to happen before that?');}});}

/* Feelings Scale & Body Clues */
const FS=[['My little brother ripped my drawing!','mad',[4,5]],['I have a spelling test tomorrow.','worried',[2,4]],['My friend can’t come to my party.','sad',[3,4]],['My pencil tip broke.','annoyed',[1,2]],['Someone took my seat at lunch.','mad',[2,3]],['I’m starting a new camp tomorrow.','worried',[3,4]],['My fish is sick.','sad',[3,5]],['My game froze and I lost my level!','annoyed',[2,4]]];
const FS_FACE={mad:'upset',worried:'nervous',sad:'sad',annoyed:'upset'};
const FS_CLUE={mad:[['face','🔥 Hot face'],['hands','✊ Tight fists'],['heart','💓 Fast heartbeat'],['jaw','😬 Clenched teeth']],worried:[['tummy','🦋 Butterflies in my tummy'],['heart','💓 Fast heartbeat'],['hands','🫨 Shaky hands'],['face','😰 Sweaty face']],sad:[['eyes','💧 Teary eyes'],['body','🫠 Heavy, slow body'],['throat','😶 Lump in my throat'],['heart','💔 Achy chest']],annoyed:[['face','😤 Huffy breathing'],['hands','✊ Tight fists'],['jaw','😬 Clenched teeth']]};
const FS_FAKE=[['face','😄 Big smile'],['body','🤸 Bouncy, happy body'],['tummy','🍕 Hungry tummy'],['eyes','😴 Sleepy eyes']];
const BODY_PT={face:[50,16],eyes:[50,14],jaw:[50,22],throat:[50,30],heart:[44,40],tummy:[50,54],hands:[18,58],body:[50,70]};
let fsI=0;
function drawScale(){zCur='scale';slWho={A:'riki',B:'friend'};const it=FS[fsI%FS.length];const [line,feel,[lo,hi]]=it;let stage=1,found=0,picked=null;
 const t=zShell('📏 Feelings Scale',`${slSceneHTML('riki','friend')}<div class="fs-q" id="fsQ"></div><div id="fsA"></div><p class="sl-note" id="slNote" hidden></p><button class="sl-big" id="slNext" hidden>Next feeling →</button>`);
 const ask=(q,html)=>{$id('fsQ').textContent=q;$id('fsA').innerHTML=html;if(window.RikiFit)RikiFit();};
 const step1=()=>{ask(`How big is Riki’s ${feel} feeling?`,`<div class="fs-scale">${[1,2,3,4,5].map(n=>`<button class="fs-n" data-n="${n}" style="--c:${['#58c98a','#a6d96a','#ffd34d','#ffa24d','#ff5f6d'][n-1]}"><b>${n}</b><small>${['Tiny','Small','Medium','Big','Huge'][n-1]}</small></button>`).join('')}</div>`);
  document.querySelectorAll('.fs-n').forEach(b=>b.onclick=()=>{const n=+b.dataset.n;if(n>=lo&&n<=hi){picked=n;audio('good');b.classList.add('on');slSay('A',`Yes, it feels like a ${n}.`,FS_FACE[feel]);setTimeout(()=>zLive(t)&&step2(),900);}else{zMiss();audio('tap');b.classList.remove('no');void b.offsetWidth;b.classList.add('no');zNote(n<lo?'Hmm, Riki looks more upset than that. Look at her face.':'Hmm, is it really that huge? What size problem is it?');}});};
 const step2=()=>{$id('slNote').hidden=true;const real=zShuf(FS_CLUE[feel]).slice(0,3);const opts=zShuf([...real,...zShuf(FS_FAKE).slice(0,3)]);
  ask('Where might Riki feel it in her body? Find 2 clues.',`<div class="fs-body"><svg viewBox="0 0 100 90" class="fs-sil"><circle cx="50" cy="16" r="12" fill="#ffd9c4"/><path d="M34 34 q16 -8 32 0 l4 30 h-40z" fill="#ffc1d8"/><path d="M34 36 l-16 22 M66 36 l16 22 M42 64 v22 M58 64 v22" stroke="#ffd9c4" stroke-width="7" stroke-linecap="round"/><g id="fsDots"></g></svg><div class="fs-chips">${opts.map((o,i)=>`<button class="fs-chip" data-i="${i}">${o[1]}</button>`).join('')}</div></div>`);
  document.querySelectorAll('.fs-chip').forEach(b=>b.onclick=()=>{if(b.disabled)return;const o=opts[+b.dataset.i];b.disabled=true;if(real.includes(o)){found++;b.classList.add('ok');audio('good');const [x,y]=BODY_PT[o[0]];$id('fsDots').insertAdjacentHTML('beforeend',`<circle cx="${x}" cy="${y}" r="7" class="fs-glow"/>`+(o[0]==='hands'?`<circle cx="${100-x}" cy="${y}" r="7" class="fs-glow"/>`:''));if(found>=2)setTimeout(()=>zLive(t)&&step3(),700);}else{zMiss();b.classList.add('bad');audio('tap');zNote('That clue doesn’t match a '+feel+' feeling.');}});};
 const step3=()=>{$id('slNote').hidden=true;const big=picked>=4,mid=picked===3;const right=big?'Take 5 big breaths and ask a grown-up for help':mid?'Take a short break, then try again':'Shrug, say “oh well,” and keep going';const wrong=big?'Just ignore it and keep yelling':'Scream for a grown-up right away';
  const opts=trimOpts(zShuf([[right,1],[wrong,0],['Throw something',0]]),o=>o[1]);
  ask(`It’s a ${picked}. Which calm tool fits?`,`<div class="sl-choices">${opts.map((o,i)=>`<button class="sl-choice c${i}" data-i="${i}">${o[0]}</button>`).join('')}</div>`);
  if(easy('calm'))hintBtn($id('fsA'),()=>[...document.querySelectorAll('#fsA .sl-choice')].find(b=>opts[+b.dataset.i][1]));
  document.querySelectorAll('#fsA .sl-choice').forEach(b=>b.onclick=async()=>{const o=opts[+b.dataset.i];if(o[1]){document.querySelectorAll('#fsA .sl-choice').forEach(x=>x.disabled=true);audio('good');slGain(1);slFx(['🫧','💙','✨'],8);slHush('A');await slSay('A',`${o[0]}… Ahh. I feel ${picked>2?'calmer':'fine'} now.`,'happy');if(!zLive(t))return;fsI++;const nx=$id('slNext');nx.hidden=false;nx.onclick=drawScale;}else{zMiss();audio('tap');b.disabled=true;zNote(o[0]==='Throw something'?'That makes the feeling bigger. Try a calm tool.':'Does that tool match the size of the feeling?');}});};
 (async()=>{await slWait(250);await slSay('A',line,FS_FACE[feel]);if(zLive(t))step1();})();}

/* My Calm Plan (printable) */
function drawCalmPlan(){zCur='calmplan';const P=zSave.calmPlan||{clues:[],tools:[],people:[]};
 const CL=['🔥 Hot face','✊ Tight fists','💓 Fast heart','🦋 Butterflies','💧 Teary eyes','😬 Clenched teeth','🗯️ Loud voice','🫨 Shaky'],TL=['🎈 Balloon breaths','🔢 Count to 10','🧸 Squeeze a stuffy','🎧 Music','🚶 Short walk','💧 Drink water','🖍️ Draw it','🛋️ Calm corner','🤗 A hug'],PP=['👩 Mom','👨 Dad','👩‍🏫 Teacher','👵 Grandma','👭 A friend','🐶 My pet'];
 const row=(k,title,list)=>`<h3 class="cp-h">${title}</h3><div class="fs-chips">${list.map(x=>`<button class="fs-chip ${P[k].includes(x)?'ok':''}" data-k="${k}" data-v="${x}">${x}</button>`).join('')}</div>`;
 const t=zShell('📝 My Calm Plan',`<p class="sl-note">Pick what fits YOU. Then print it for the fridge!</p>${row('clues','1. My body clues',CL)}${row('tools','2. My calm tools',TL)}${row('people','3. People who help me',PP)}<div class="cp-card" id="cpCard"></div><div class="pd-row"><button class="sl-big" id="cpPrint">🖨️ Print my plan</button></div>`);
 const card=()=>{$id('cpCard').innerHTML=`<div class="cp-in">${window.RikiArt?'<span class="cp-doll">'+RikiArt.doll(RikiArt.look('riki'),'wave','excited',true)+'</span>':''}<h2>Riki’s Calm Plan</h2><p><b>When I notice:</b> ${P.clues.join(', ')||'…'}</p><p><b>I can:</b> ${P.tools.join(', ')||'…'}</p><p><b>I can ask:</b> ${P.people.join(', ')||'…'}</p><p class="cp-foot">I can calm down. Feelings come and go. 💖</p></div>`;};card();
 document.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{const a=P[b.dataset.k],v=b.dataset.v;const i=a.indexOf(v);if(i>=0)a.splice(i,1);else a.push(v);b.classList.toggle('ok');zSave.calmPlan=P;zPut();audio('tap');card();if(P.clues.length&&P.tools.length&&P.people.length&&!zSave.done.calm?.plan){(zSave.done.calm=zSave.done.calm||{}).plan=1;slGain(1);zPut();}});
 $id('cpPrint').onclick=()=>{document.body.classList.add('cp-printing');setTimeout(()=>{try{window.print();}catch(e){}setTimeout(()=>document.body.classList.remove('cp-printing'),500);},50);};}

/* Wait For It (impulse control) */
const WF_DIST=['🐱 A kitty runs by!','✨ Sparkles!','🔔 DING DING!','👀 Psst… just eat it!','🎈 A balloon!','🍫 Chocolate!','📱 TAP ME!','🦄 A unicorn!'];
function drawWaitFor(){zCur='waitfor';let L=zLvl('waitfor',5),round=0,wins=0;
 const t=zShell('🧁 Wait For It',`<div class="wf-stage" id="wfStage"><div class="wf-plate" id="wfPlate">🧁</div><div class="wf-dist" id="wfDist"></div><div class="wf-face">${window.RikiArt?RikiArt.doll(RikiArt.look('riki'),'stand','happy',true):''}</div><div class="wf-talk" id="wfTalk">Wait the whole time and get TWO cupcakes!</div></div><div class="z-bar"><i id="wfBar" style="width:0"></i></div><button class="wf-hold" id="wfHold">Press and HOLD to wait</button><div class="sl-score"><span id="wfR">Round 1/3</span><span id="wfS">⏳ ${L}s</span></div><p class="sl-note" id="slNote">Tricks: hum a song, count, or look away!</p>`);
 const hold=$id('wfHold'),bar=$id('wfBar'),dist=$id('wfDist');let start=0,raf=0,spawn=0,over=false;
 const talk=s=>{const w=$id('wfTalk');if(w)w.textContent=s;};
 const end=ok=>{start=0;cancelAnimationFrame(raf);clearInterval(spawn);dist.innerHTML='';hold.classList.remove('on');round++;
  if(ok){wins++;slGain(1);audio('good');$id('wfPlate').textContent='🧁🧁';talk('I waited! TWO cupcakes! 🎉');try{celebrate();}catch(e){}L=Math.min(20,L+2);zSave.lvl.waitfor=L;zPut();}
  else{zMiss();audio('tap');$id('wfPlate').textContent='🧁';talk('Oops, I let go. That was hard! Try a trick next time.');}
  $id('wfS').textContent=`⏳ ${L}s`;if(round>=3){over=true;hold.disabled=true;zDone(t,wins===3?'🧁 3 for 3! Super waiting power!':`🧁 You waited ${wins} of 3 times!`,null,wins?2:0);}else{$id('wfR').textContent=`Round ${round+1}/3`;setTimeout(()=>{if(zLive(t)){$id('wfPlate').textContent='🧁';bar.style.width='0';talk('Ready? Hold to wait!');}},1400);}};
 const loop=()=>{if(!start||!zLive(t))return;const p=(Date.now()-start)/(L*1000);bar.style.width=Math.min(100,p*100)+'%';if(p>=1){end(true);return;}raf=requestAnimationFrame(loop);};
 const down=e=>{e.preventDefault();if(over||start)return;start=Date.now();hold.classList.add('on');talk('I can wait… I can wait…');loop();
  spawn=setInterval(()=>{if(!zLive(t)||!start){clearInterval(spawn);return;}const s=document.createElement('span');s.textContent=WF_DIST[Math.floor(Math.random()*WF_DIST.length)];s.style.left=(5+Math.random()*60)+'%';s.style.top=(5+Math.random()*60)+'%';dist.appendChild(s);setTimeout(()=>s.remove(),1600);if(Math.random()<.35)talk(['Hum hum hum…','One… two… three…','I’ll look away!','Almost there!'][Math.floor(Math.random()*4)]);},900);};
 const up=()=>{if(!start)return;const p=(Date.now()-start)/(L*1000);if(p<1)end(false);};
 hold.addEventListener('pointerdown',down);hold.addEventListener('pointerup',up);hold.addEventListener('pointerleave',up);hold.addEventListener('pointercancel',up);}

