/* Flat menu (Claude, Oct 30): every game visible on one page, grouped by skill. Watch is an optional tile; no required path. */
const zDupSeen=()=>{const seen=new Set();return UNITS.map(u=>({...u,games:u.games.filter(g=>{if(seen.has(g[0]))return false;seen.add(g[0]);return true;})}));};
todaysMission=function(){const ranked=[...UNITS].filter(u=>u.games.length).sort((a,b)=>unitScore(a.id)-unitScore(b.id));const u=ranked[new Date().getDate()%2?0:1]||ranked[0];const g=[...u.games].sort((a,b)=>(zSave.stars[a[0]]||0)-(zSave.stars[b[0]]||0))[0];return {u,g,label:g[2],run:()=>runGame(g[0])};};
newHub=function(){zStop();zCur='';lastUnit=null;game='sel';const tm=todaysMission();const list=zDupSeen();
 app.innerHTML=`<section class="sel-hero z-hero"><h1>🏙️ Riki’s Skill City</h1><button class="secondary" id="backHebrewNew">🎮 Hebrew Games</button></section>
  <section class="panel fm"><button class="sc-today" id="scToday" style="--zc:${tm.u.color}"><span class="sc-tag">🎯 Today’s pick · ${tm.u.ic} ${tm.u.name}</span><b>${tm.g[1]} ${tm.label}</b><span>Tap to play →</span></button>
  <h3 class="fm-h">🎪 Arcade</h3>${arcRow()}
  ${list.map(u=>`<div class="fm-skill" style="--zc:${u.color}"><h3 class="fm-h">${u.ic} ${u.name}</h3><div class="fm-row"><button class="fm-g fm-watch" data-watch="${u.id}" type="button"><b>🎬</b><span>Watch a story</span></button>${u.games.map(([id,e,n])=>`<button class="fm-g" data-zg="${id}" type="button"><b>${e}</b><span>${n}</span>${zSave.stars[id]?`<i>⭐${zSave.stars[id]}</i>`:''}</button>`).join('')}</div></div>`).join('')}
  <div class="sc-row"><button class="secondary" id="scCheck">🧭 Check-in</button><button class="secondary" id="scGrown">👩‍🏫 Grown-ups</button></div></section>`;
 $id('backHebrewNew').onclick=menu;$id('scToday').onclick=()=>{audio('tap');tm.run();};$id('scCheck').onclick=()=>{audio('tap');drawCheck();};$id('scGrown').onclick=()=>{audio('tap');grownGate(()=>grownups());};
 document.querySelectorAll('[data-zg]').forEach(b=>b.onclick=()=>runGame(b.dataset.zg));
 document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>{audio('tap');drawWatch(b.dataset.watch);window.scrollTo(0,0);});
 wireArcRow();
 if(typeof selClassicHub==='function'){const mb=document.createElement('button');mb.className='secondary';mb.style.cssText='display:block;margin:14px auto 0';mb.textContent='📚 More Social Skills adventures';mb.onclick=()=>{audio('tap');selClassicHub();};app.querySelector('.panel').appendChild(mb);}
 window.scrollTo(0,0);};
