/* 6. Dance Class: copy the move combo from memory; freeze on the whistle (only when it's for you) */
const DC_MOVES=[['spin','💫','Spin'],['clap','👏','Clap'],['jump','⬆️','Jump'],['wave','🙌','Wave']];
function drawDance(){zCur='dance';let lv=0,score=0;const LV=[2,3,3,4,4];
 const t=zShell('💃 Dance Class',`${g6Top('teacher','Coach')}<div class="dc-floor" id="dcF"><span class="dc-doll" id="dcDoll">${dollHTML('happy')}</span><div class="dc-light" id="dcL"></div></div><div class="dc-pad">${DC_MOVES.map(m=>`<button type="button" data-m="${m[0]}"><b>${m[1]}</b>${m[2]}</button>`).join('')}</div><div class="ag-msg" id="agM"></div>${g6Pips(LV.length,0)}`);
 let combo=[],at=0,frozen=false,freezeOk=true,busy=true;
 const anim=m=>{const d=$id('dcDoll');if(!d)return;d.className='dc-doll mv-'+m;setTimeout(()=>{if(d.isConnected)d.className='dc-doll';},450);};
 const round=async()=>{if(!zLive(t))return;if(lv>=LV.length){zDone(t,`💃 Recital done! ${score}/${LV.length} perfect routines.`,drawDance,Math.max(2,score));return;}
  busy=true;combo=Array.from({length:LV[lv]},()=>DC_MOVES[Math.floor(Math.random()*4)]);at=0;freezeOk=true;window.RikiG6.dc=()=>({combo:combo.map(m=>m[0]),at,frozen,busy});
  await g6Talk('teacher','Watch and listen: '+combo.map(m=>m[2]).join(', ')+'!',{hideAfter:1400+LV[lv]*500});if(!zLive(t))return;busy=false;
  if(lv>=1){const real=lv<3||Math.random()<.6;setTimeout(async()=>{if(!zLive(t)||busy)return;if(real){frozen=true;$id('dcL').className='dc-light red';g6Say('teacher','Freeze!');audio('tap');setTimeout(()=>{frozen=false;const l=$id('dcL');if(l)l.className='dc-light';},1800);}else{$id('dcL').className='dc-light fake';g6Say('teacher','Maya, freeze!');setTimeout(()=>{const l=$id('dcL');if(l)l.className='dc-light';},1500);}},900+Math.random()*900);}};
 document.querySelectorAll('[data-m]').forEach(b=>b.onclick=()=>{if(busy||!combo[at])return;if(frozen){freezeOk=false;zMiss();audio('tap');dollReact(false);g6Msg('🥶 FREEZE means stop! Wait until the light goes off.',false);return;}const m=b.dataset.m;anim(m);
  if(m===combo[at][0]){at++;audio('tap');if(at===combo.length){busy=true;const perfect=freezeOk;if(perfect){score++;slGain(1);}audio('good');dollReact(true);g6Msg(perfect?'🌟 Perfect routine!':'✅ Routine done! (watch the freeze next time)',true);lv++;const pp=document.querySelector('.g6-pips');if(pp)pp.outerHTML=g6Pips(LV.length,lv);setTimeout(round,1300);}}
  else{zMiss();audio('tap');dollReact(false);g6Msg('Oops, wrong move! Start the routine again from the top.',false);at=0;}});
 setTimeout(round,400);}

