/* Full-body dolls that move: jump, wave, listen, think, nod, reach, celebrate (uses the live doll rig). Claude, Oct 30 */
const RIG_FOR={excited:'hop',happy:'rk-motion-nod',think:'rk-motion-think',surprised:'hop',nervous:'rk-motion-listen'};
function rigMove(el,cls,ms=1800){if(!el)return;['hop','walk','rk-motion-nod','rk-motion-think','rk-motion-listen','rk-motion-celebrate','rk-motion-reach'].forEach(c=>el.classList.remove(c));void el.offsetWidth;el.classList.add(cls);clearTimeout(el._rig);el._rig=setTimeout(()=>el.classList.remove(cls),ms);}
if(!document.getElementById('rigCss')){const st=document.createElement('style');st.id='rigCss';st.textContent='.sl-actor.hop>span[id^=slF]{display:inline-block;animation:rigHop .62s cubic-bezier(.3,1.4,.5,1) 2}.sl-actor.rk-motion-celebrate>span[id^=slF]{display:inline-block;animation:rigHop .5s cubic-bezier(.3,1.4,.5,1) 3}.sl-actor.walk>span[id^=slF]{display:inline-block;animation:rigBob .32s ease-in-out infinite}@keyframes rigHop{0%,100%{transform:translateY(0)}40%{transform:translateY(-16px)}}@keyframes rigBob{50%{transform:translateY(-4px)}}@media (prefers-reduced-motion:reduce){.sl-actor>span[id^=slF]{animation:none!important}}';document.head.appendChild(st);}
function rigWave(el){const svg=el&&el.querySelector('svg[data-joint-character]');if(!svg)return;svg.dataset.rigAction='wave';setTimeout(()=>{if(svg.isConnected)svg.dataset.rigAction='stand';},1800);}
const slExprRig=slExpr;slExpr=function(side,expr,anim){slExprRig(side,expr,anim);const a=$id('sl'+side);if(!a)return;if(anim==='bounce'||expr==='excited')rigMove(a,expr==='excited'&&anim==='bounce'?'rk-motion-celebrate':'hop');else if(RIG_FOR[expr]&&anim!=='shake')rigMove(a,RIG_FOR[expr],1600);};
const slSayRig=slSay;slSay=function(side,text,expr){const other=$id('sl'+(side==='A'?'B':'A'));if(other)rigMove(other,'rk-motion-listen',Math.min(4000,900+String(text).length*45));const me=$id('sl'+side);if(/\b(hi|hello|hey|bye|see you|welcome)\b/i.test(text))setTimeout(()=>rigWave(me),60);return slSayRig.apply(this,arguments);};
const thRig=slTheater;slTheater=async function(scene,choice,good){const act=actionFor(String(choice),good),A=$id('slA');if(['give','share'].includes(act))rigMove(A,'rk-motion-reach',1700);else if(act==='away')rigMove(A,'walk',1400);else if(['kind','wait'].includes(act))rigMove(A,'rk-motion-nod',1500);else if(act==='grownup')rigWave(A);return thRig.apply(this,arguments);};
