const SC3_WORDS=[['party',/party|birthday|present|gift/],['store',/store|\bshop\b|shopping|\bbuy|toy aisle|grocery|\bcart\b|wish list|mall/],['lunchroom',/lunch|cafeteria|tray|lunchroom/],['field',/soccer|kickball|coach|basketball|baseball|relay|field day|\bgym\b|\bteam\b|good game|you lost|you won|lost the game|won the game/],['playground',/recess|playground|\btag\b|swing|slide|sandcastle|jump rope|\bball\b|four square|monkey bars/],['park',/picnic|\bpark\b|pond|field trip/],['busstop',/\bbus\b|bus stop|carpool|ride home|my ride/],['bedroom',/bedtime|\bbed\b|sleep|pajama|\bbath\b|sleepover/],['living',/\btv\b|movie|remote|tablet|screen|couch|video game|game froze|\bshow\b/],['kitchen',/dinner|kitchen|cookie|bake|bakery|juice|breakfast|cook|candy|cupcake|snack/],['library',/library|reading|book/],['hall',/hallway|cubby|locker|in line|line leader|first in line|cut in front/],['classroom',/class|teacher|answer|spelling|raining|go outside|ms\. dana|\btest\b|pencil|desk|homework|marker|crayon|drawing|school|art\b|project|math|new here|poster|raise.*hand/],['playroom',/block|tower|lego|puzzle|doll|board game|playdate|play house|toys? at home/]];
function sc3Pick(text){const s=String(text||'').toLowerCase();for(const [k,re] of SC3_WORDS)if(re.test(s))return k;if(/\bmom\b|\bdad\b|brother|sister|grandma/.test(s))return 'living';if(/ms\.|teacher/.test(s))return 'classroom';return 'playground';}
function sc3Apply(sc,key){if(!sc||!key)return;sc.dataset.set=key;sc3Get(key,url=>{if(!sc.isConnected||sc.dataset.set!==key)return;sc.style.backgroundImage=`url(${url})`;sc.classList.add('sc3');});}
let sc3Next=null;const sc3Use=k=>{sc3Next=k;};
const sc3Scan=()=>{document.querySelectorAll('.sl-scene:not([data-set])').forEach(sc=>{sc.dataset.set='?';setTimeout(()=>{if(!sc.isConnected||sc.dataset.said)return;const host=sc.closest('section,.panel')||document.body;const txt=[...host.querySelectorAll('.sl-bubble,.riki-story-theater,.zg-ask,.sl-card,h2,h3,p,.acc-clues')].map(e=>e.textContent).join(' ')+' '+(zCur||'');const k=sc3Next||sc3Pick(txt+' '+(slWho&&slWho.B==='teacher'?'teacher':slWho&&slWho.B==='mom'?'mom':''));sc3Next=null;sc3Apply(sc,k);},450);});};
new MutationObserver(()=>sc3Scan()).observe(document.body,{childList:true,subtree:true});
