function p3Render(kind){if(P3.cache[kind])return P3.cache[kind];if(!window.THREE)return null;
 if(P3_ITEM[kind]&&window.RK3&&RK3.thumb){try{const u=RK3.thumb(P3_ITEM[kind]);if(u){P3.cache[kind]=u;return u;}}catch(e){}}
 const mk=P3_MAKE[kind];if(!mk)return null;const {R,s,cam}=p3Rig();const g=new THREE.Group();mk(g);s.add(g);g.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(g),sz=b.getSize(new THREE.Vector3()),c=b.getCenter(new THREE.Vector3());g.position.sub(c);
 const r=Math.max(sz.x,sz.y,sz.z)*.62,d=r/Math.sin(cam.fov*Math.PI/360)*1.05;cam.position.set(0,d*.35,d*.94);cam.lookAt(0,0,0);cam.updateProjectionMatrix();R.render(s,cam);const u=R.domElement.toDataURL('image/png');s.remove(g);P3.cache[kind]=u;return u;}
