const CP_KEY='projroom';
const CP_SPOTS={teacher:[-1.25,-.6],zoe:[1.0,-.05],lily:[2.3,1.35],ava:[-2.0,1.4],luna:[-2.7,.55]};
const CP_OBJS={hamster:[-3.0,1.25,-1.3,'🐹'],cubby:[-3.0,.55,-1.3,'🗄️'],shelf:[3.0,.8,-1.3,'📚'],sink:[1.55,.7,-1.42,'🚰'],board:[-.2,2.0,-1.56,'🟩'],desk:[-1.75,.7,-.95,'🍎'],lilydesk:[2.35,.7,.75,'✏️'],table:[.2,.7,-.15,'🎨']};
const CP_NAMES={teacher:'Ms. Dana',zoe:'Zoe',lily:'Lily',ava:'Ava',luna:'Luna',maya:'Maya',riki:'Riki'};
const CP_VOICE={teacher:'teacher',zoe:'friend2',maya:'friend',lily:'friend',ava:'friend2',luna:'friend',riki:'riki'};
const cpDoll=(id,expr)=>{try{if(id==='teacher')return slFace('teacher',expr||'happy');if(window.RikiArt)return RikiArt.doll(RikiArt.look(id),'stand',expr||'happy',false);}catch(e){}return slFace(id==='zoe'?'friend2':'friend',expr);};
function cpUnproj(px,py){const cam=sc3Cam(CP_KEY);const v=new THREE.Vector3(px/50-1,1-py/50,.5).unproject(cam);const d=v.sub(cam.position).normalize();const t=-cam.position.y/d.y;return [cam.position.x+d.x*t,cam.position.z+d.z*t];}
let CP=null;
function cpPlace(id){const el=CP&&CP.els[id];if(!el)return;const [x,z]=CP.pos[id];const f=sc3Proj(CP_KEY,x,0,z),h=sc3Proj(CP_KEY,x,1.75,z);el.style.left=f[0]+'%';el.style.top=f[1]+'%';el.style.height=(f[1]-h[1])+'%';el.style.zIndex=Math.round(f[1]*10);}
const cpWait=ms=>new Promise(r=>setTimeout(r,ms));
async function cpWalk(x,z){if(!CP)return;x=Math.max(-3.2,Math.min(3.2,x));z=Math.max(-.55,Math.min(2.3,z));const [x0,z0]=CP.pos.riki;const d=Math.hypot(x-x0,z-z0);if(d<.05)return;const el=CP.els.riki;el.classList.add('walk');el.classList.toggle('flip',x<x0);const ms=Math.min(1400,300+d*330);el.style.transitionDuration=ms+'ms';CP.pos.riki=[x,z];cpPlace('riki');await cpWait(ms);el.classList.remove('walk');}
async function cpGoTo(id){const p=CP.pos[id]||(CP_OBJS[id]?[CP_OBJS[id][0],CP_OBJS[id][2]]:null);if(!p)return;const [x,z]=p;const side=x>CP.pos.riki[0]?-1:1;await cpWalk(x+side*.62,Math.max(z+.15,-.5));}
async function cpSay(id,text,expr){if(!CP)return;const host=CP.els[id]||CP.els.riki;const b=document.createElement('div');b.className='cp-bub';b.textContent=text;host.appendChild(b);if(expr&&CP.els[id]){const img=CP.els[id].querySelector('.cp-img');if(img)img.innerHTML=cpDoll(id,expr);}
 const st=Date.now();try{await g6Say(CP_VOICE[id]||'friend',text);}catch(e){}const left=Math.max(0,Math.min(2600,700+text.length*45)-(Date.now()-st));await cpWait(left);b.classList.add('out');setTimeout(()=>b.remove(),220);}
function cpExpr(id,e){const img=CP&&CP.els[id]&&CP.els[id].querySelector('.cp-img');if(img)img.innerHTML=cpDoll(id,e);}
function cpGoal(text,marks=[]){CP.goal=text;const g=$id('cpGoalT');if(g)g.textContent=text;document.querySelectorAll('.cp-mark').forEach(m=>m.remove());marks.forEach(id=>{const host=CP.els[id]||CP.objEls[id];if(!host)return;const m=document.createElement('span');m.className='cp-mark';m.textContent='⬇️';host.appendChild(m);});}
const cpPanel=html=>{const p=$id('cpPanel');if(p){p.innerHTML=html;p.hidden=!html;if(html)p.scrollIntoView({block:'nearest',behavior:'smooth'});}return p;};
function cpWaitTap(handlers){return new Promise(res=>{CP.H=handlers;CP.done=v=>{CP.H={};res(v);};});}
function cpAsk(q,opts){return new Promise(res=>{const p=cpPanel(`<p class="cp-q">${q}</p>${opts.map((o,i)=>`<button type="button" class="cp-opt" data-i="${i}">${o[0]}</button>`).join('')}`);p.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{audio('tap');cpPanel('');res(+b.dataset.i);});});}
const CP_DEF={teacher:['Keep up the good work, Riki!','Remember: ask your partner first!'],lily:['I’m busy with my own project!','Shh, I’m counting my beads.'],ava:['Hi Riki! I like your bow!','Our group is making a castle.'],luna:['Did you see the hamster? He’s so cute!','I love art day!'],maya:['Hi Riki!','I’m almost done with my reading.'],zoe:['Hi partner!'],
 hamster:['🐹 Squeak squeak!','🐹 *nibbles a seed*','🐹 *runs on the wheel*'],shelf:['Lots of books and supplies.'],sink:['💦 Splash! Clean hands.'],board:['A B C… 1 + 1 = 2!'],desk:['That’s Ms. Dana’s desk. 🍎'],lilydesk:['Lily’s desk.'],table:['Our art table!'],cubby:['The class cubbies.']};
async function cpTap(id){if(!CP||CP.busy)return;CP.busy=true;try{await cpGoTo(id);const h=CP.H&&CP.H[id];if(h){const r=await h();if(r&&CP.done)CP.done(id);}else{const L=CP_DEF[id];if(L){const line=L[Math.floor(Math.random()*L.length)];if(CP_OBJS[id]){if(id==='hamster'){const o=CP.objEls.hamster;o.classList.remove('wig');void o.offsetWidth;o.classList.add('wig');}await cpSay('riki',line.replace(/^(🐹|💦) /,'$1 '));}else await cpSay(id,line);}}}finally{CP.busy=false;}}

/* mini tasks */
function cpMerge(mine,theirs,result){return new Promise(res=>{let on=[];const p=cpPanel(`<p class="cp-q">🧠 Plan together! Drag ideas onto the plan board.</p><div class="cp-ideas"><div class="cp-idea me" data-k="me">${mine[0]} <small>Riki’s idea</small></div><div class="cp-idea them" data-k="them">${theirs[0]} <small>${theirs[1]}’s idea</small></div></div><div class="cp-board" id="cpBoard"><b>📋 Our plan</b><div id="cpOn"></div></div><button type="button" class="sl-big" id="cpOk" hidden>That’s our plan!</button>`);
 const board=$id('cpBoard');hoTapTarget(board);let missed=false;
 p.querySelectorAll('.cp-idea').forEach(el=>hoDrag(el,()=>[board],()=>{if(on.includes(el.dataset.k))return;on.push(el.dataset.k);audio('tap');el.classList.add('used');$id('cpOn').innerHTML+=`<span>${el.firstChild.textContent}</span>`;$id('cpOk').hidden=false;if(on.length===2){$id('cpOn').innerHTML=`<span class="combo">${result}</span>`;audio('good');}}));
 $id('cpOk').onclick=async()=>{if(on.length<2){if(!missed){missed=true;zMiss();}cpExpr(theirs[2],'sad');await cpSay(theirs[2],on[0]==='me'?'Hey… what about my idea?':'What about YOUR idea, Riki?','sad');cpExpr(theirs[2],'happy');return;}cpPanel('');res(!missed);};});}
function cpSplit(jobs,partner,wants){return new Promise(res=>{let missed=false;const p=cpPanel(`<p class="cp-q">✂️ Split the jobs. Drag each job to Riki or ${CP_NAMES[partner]}.</p><div class="cp-jobs" id="cpJobs">${jobs.map((j,i)=>`<div class="cp-job" data-i="${i}">${j[0]} ${j[1]}${j[2]?' ⭐':''}</div>`).join('')}</div><div class="cp-cols"><div class="cp-col" data-who="riki"><b>${'Riki'}</b><div class="cp-in"></div></div><div class="cp-col" data-who="${partner}"><b>${CP_NAMES[partner]}</b><div class="cp-in"></div></div></div><small class="cp-tip">⭐ = super fun job</small><button type="button" class="sl-big" id="cpOk" hidden>Done splitting!</button>`);
 const cols=[...p.querySelectorAll('.cp-col')];cols.forEach(hoTapTarget);const where={};
 const draw=()=>{cols.forEach(c=>{c.querySelector('.cp-in').innerHTML=Object.entries(where).filter(([,w])=>w===c.dataset.who).map(([i])=>`<button type="button" class="cp-chip" data-i="${i}">${jobs[i][0]} ${jobs[i][1]}${jobs[i][2]?' ⭐':''}</button>`).join('');c.querySelectorAll('.cp-chip').forEach(b=>b.onclick=e=>{if(hoSel)return;e.stopPropagation();delete where[b.dataset.i];p.querySelector(`.cp-job[data-i="${b.dataset.i}"]`).classList.remove('used');draw();});});$id('cpOk').hidden=Object.keys(where).length<jobs.length;};
 p.querySelectorAll('.cp-job').forEach(el=>hoDrag(el,()=>cols,t=>{where[el.dataset.i]=t.dataset.who;el.classList.add('used');audio('tap');draw();}));
 $id('cpOk').onclick=async()=>{const mine=jobs.filter((j,i)=>where[i]==='riki'),theirs=jobs.filter((j,i)=>where[i]===partner);let msg=null;
  if(mine.length>theirs.length)msg='Hey, you have way more jobs than me! Can I have one?';else if(theirs.length>mine.length)msg='Whoa, that’s a lot for me! Can you take one?';else if(!theirs.some(j=>j[2]))msg='You got all the fun jobs… I want a fun one too!';else if(!mine.some(j=>j[2]))msg='Are you sure? You should get a fun job too!';else if(wants!=null&&where[wants]!==partner)msg=`Remember, I really wanted ${jobs[wants][1].toLowerCase()}…`;
  if(msg){if(!missed){missed=true;zMiss();}cpExpr(partner,'think');await cpSay(partner,msg,'think');cpExpr(partner,'happy');return;}
  audio('good');cpPanel('');await cpSay(partner,'That’s fair! Let’s do it!','excited');res({ok:!missed,mine});};});}
function cpTally(chips,cols){return new Promise(res=>{const p=cpPanel(`<p class="cp-q">📊 Count the votes! Drag each answer into its column.</p><div class="cp-jobs">${chips.map((c,i)=>`<div class="cp-job" data-i="${i}">${c[1]} <small>${c[0]}</small></div>`).join('')}</div><div class="cp-cols three">${cols.map(c=>`<div class="cp-col" data-c="${c}"><b>${c}</b><div class="cp-in"></div></div>`).join('')}</div>`);
 const cs=[...p.querySelectorAll('.cp-col')];cs.forEach(hoTapTarget);let n=0,missed=false;
 p.querySelectorAll('.cp-job').forEach(el=>hoDrag(el,()=>cs,t=>{const c=chips[+el.dataset.i];if(!c[1].includes(t.dataset.c)){if(!missed){missed=true;zMiss();}audio('tap');zNote('Hmm, does that answer go there?');return;}audio('good');el.remove();t.querySelector('.cp-in').innerHTML+='<i>✋</i>';if(++n===chips.length){setTimeout(()=>{cpPanel('');res(!missed);},500);}}));});}
function cpFetch(list){return new Promise(res=>{const got=new Set();const draw=()=>{const p=$id('cpPanel');p.hidden=false;p.innerHTML=`<p class="cp-q">🧺 Get your supplies</p><div class="cp-list">${list.map(([id,e,n])=>`<span class="${got.has(id)?'on':''}">${e} ${n} ${got.has(id)?'✅':''}</span>`).join('')}</div>`;};draw();
 const H={};list.forEach(([id,e,n,where,line])=>{H[where]=async()=>{if(got.has(id)){await cpSay('riki','I already got the '+n+'.');return false;}got.add(id);audio('good');await cpSay('riki',line||('Got the '+n+'! '+e));draw();if(got.size===list.length){await cpWait(300);cpPanel('');res(true);return true;}cpGoal('Get: '+list.filter(x=>!got.has(x[0])).map(x=>x[2]).join(', '),list.filter(x=>!got.has(x[0])).map(x=>x[3]));return false;};});
 CP.H=Object.assign({},CP.H,H);cpGoal('Get: '+list.map(x=>x[2]).join(', '),list.map(x=>x[3]));});}
function cpDecorate(partner){return new Promise(res=>{const cols=['#ff5d8f','#5ab8ff','#ffb000','#7ed98d','#b07cff'];let col=cols[0],colored=new Set(),stick=0;const word='BAKE SALE';
 const p=cpPanel(`<p class="cp-q">🎨 Your job: color the letters and add 3 cupcake stickers!</p><div class="cp-poster" id="cpPoster"><div class="cp-word">${[...word].map((c,i)=>c===' '?'<span class="sp"></span>':`<button type="button" class="cp-let" data-i="${i}">${c}</button>`).join('')}</div><div class="cp-stz" id="cpStz"></div><div class="cp-glit" id="cpGlit"></div></div><div class="cp-pal">${cols.map(c=>`<button type="button" class="cp-col-b" data-c="${c}" style="background:${c}"></button>`).join('')}<div class="cp-stk" id="cpStk">🧁</div><div class="cp-stk" id="cpStk2">🧁</div><div class="cp-stk" id="cpStk3">🧁</div></div>`);
 const fin=()=>{if(colored.size>=8&&stick>=3){clearInterval(gl);audio('good');setTimeout(()=>res(true),500);}};
 p.querySelectorAll('.cp-col-b').forEach(b=>b.onclick=()=>{col=b.dataset.c;p.querySelectorAll('.cp-col-b').forEach(x=>x.classList.toggle('on',x===b));});p.querySelector('.cp-col-b').classList.add('on');
 p.querySelectorAll('.cp-let').forEach(b=>b.onclick=()=>{b.style.color=col;b.style.textShadow=`0 3px 0 ${col}55`;colored.add(b.dataset.i);audio('tap');fin();});
 const poster=$id('cpPoster');hoTapTarget(poster);['cpStk','cpStk2','cpStk3'].forEach(id=>{const el=$id(id);hoDrag(el,()=>[poster],(t,src,ev)=>{const s=document.createElement('span');s.textContent='🧁';s.style.left=(12+stick*30)+'%';s.style.top=(stick%2?62:70)+'%';$id('cpStz').appendChild(s);el.remove();stick++;audio('good');fin();});});
 let gn=0;const gl=setInterval(()=>{if(!$id('cpGlit')){clearInterval(gl);return;}const s=document.createElement('i');s.textContent='✨';s.style.left=(Math.random()*90)+'%';s.style.top=(Math.random()*80)+'%';$id('cpGlit').appendChild(s);if(++gn===2)cpSay(partner,'I’m doing the glitter! ✨','excited');},1500);});}

