function drawClassProjects(){zCur='classproj';zStop();const t=zShell('🏫 Class Projects',`<p class="cp-intro">Walk around the classroom and work on a project with a partner!</p><div class="cp-pick">${Object.entries(CP_PROJECTS).map(([k,p])=>`<button type="button" class="cp-proj" data-p="${k}"><b>${p.ic}</b><strong>${p.name}</strong><small>${p.skill}</small>${zSave.stars['cp_'+k]?`<i>⭐${zSave.stars['cp_'+k]}</i>`:''}</button>`).join('')}<div class="cp-proj soon"><b>🌋</b><strong>Science Volcano</strong><small>Coming soon</small></div><div class="cp-proj soon"><b>🌉</b><strong>Block Bridge</strong><small>Coming soon</small></div><div class="cp-proj soon"><b>🎭</b><strong>Puppet Show</strong><small>Coming soon</small></div></div>`);
 document.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{audio('tap');cpStart(b.dataset.p);});}
function cpStart(key){const P=CP_PROJECTS[key];const t=zShell(`${P.ic} ${P.name}`,`<div class="cp-goal"><span>📋</span><b id="cpGoalT">…</b><button type="button" id="cpJob">What’s my job?</button></div><div class="cp-stage" id="cpStage"><div class="cp-load">Setting up the classroom…</div></div><div class="cp-panel" id="cpPanel" hidden></div><p class="sl-note" id="slNote" hidden></p>`);
 sc3Get(CP_KEY,async url=>{if(!zLive(t))return;const st=$id('cpStage');st.innerHTML='';st.style.backgroundImage=`url(${url})`;
  CP={t,key,els:{},objEls:{},pos:{riki:[0,2.0],...Object.fromEntries(Object.entries(CP_SPOTS))},H:{},busy:false,goal:''};window.RikiCP={state:()=>({goal:CP&&CP.goal,pos:CP&&CP.pos.riki,busy:CP&&CP.busy}),tap:id=>cpTap(id)};
  Object.entries(CP_OBJS).forEach(([id,[x,y,z,e]])=>{const o=document.createElement('button');o.type='button';o.className='cp-obj';o.dataset.id=id;o.title=id;const p=sc3Proj(CP_KEY,x,y,z);o.style.left=p[0]+'%';o.style.top=p[1]+'%';if(id==='hamster')o.innerHTML='<span class="cp-ham">🐹</span>';st.appendChild(o);CP.objEls[id]=o;o.onclick=e2=>{e2.stopPropagation();cpTap(id);};});
  ['riki',...Object.keys(CP_SPOTS)].forEach(id=>{if(key==='poster'&&['ava','luna'].includes(id)&&0)return;const el=document.createElement('div');el.className='cp-ch'+(id==='riki'?' me':'');el.dataset.id=id;el.innerHTML=`<div class="cp-img">${cpDoll(id)}</div><small>${CP_NAMES[id]}</small>`;st.appendChild(el);CP.els[id]=el;cpPlace(id);if(id!=='riki')el.onclick=e2=>{e2.stopPropagation();cpTap(id);};});
  st.onclick=async e=>{if(!CP||CP.busy)return;const r=st.getBoundingClientRect();const [x,z]=cpUnproj((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100);CP.busy=true;await cpWalk(x,z);CP.busy=false;};
  $id('cpJob').onclick=()=>{audio('tap');cpSay('riki','My job: '+CP.goal);};
  const stars=await P.run();if(!zLive(t))return;const n=Math.max(1,Math.min(3,stars));
  cpPanel(`<div class="cp-done"><b>${'⭐'.repeat(n)}${'☆'.repeat(3-n)}</b><span>Teamwork stars</span></div>`);await cpSay('teacher',n===3?'Amazing teamwork! You planned together, shared the jobs, and solved problems kindly!':n===2?'Great job working together! Next time, make sure everyone gets a say.':'You finished! Let’s keep practicing teamwork together.','excited');
  zSave.stars['cp_'+key]=Math.max(zSave.stars['cp_'+key]||0,n);slGain(n);zPut&&zPut();zDone(t,`${P.ic} Project done! ${'⭐'.repeat(n)}`,()=>cpStart(key),3+n);});}
Object.assign(ZRUN,{classproj:drawClassProjects});
