const bpPrior=drawBackpack;drawBackpack=function(){const go=()=>{bpPrior();const fix=()=>{document.querySelectorAll('.bp-item b,.bp-p').forEach(el=>{if(el.dataset.p3)return;const e=el.textContent.trim();const h=p3Img(e);if(h!==e){el.innerHTML=h;el.dataset.p3=1;}});};fix();const R=$id('bpRoom'),I=$id('bpIn');[R,I].forEach(x=>x&&new MutationObserver(fix).observe(x,{childList:true,subtree:true}));};if(window.THREE)go();else if(window.RK3&&RK3.loadThree)RK3.loadThree(go,go);else go();};
const chPrior=drawClueHunt;drawClueHunt=function(){const go=()=>{chPrior();document.querySelectorAll('.ch-clue').forEach(el=>{const e=el.textContent.trim();if(/[😮😟🤔🙂😏]/u.test(e)){el.classList.add('ch-face');el.textContent='❗';return;}const h=p3Img(e);if(h!==e)el.innerHTML=h;});};if(window.THREE)go();else if(window.RK3&&RK3.loadThree)RK3.loadThree(go,go);else go();};
