/* Three more Class Projects (Claude, Oct 30) */
function cpRecipe(steps,ms){return new Promise(res=>{const p=cpPanel(`<p class="cp-q">📋 Read the recipe card. It will hide soon!</p><ol class="cp-recipe">${steps.map(s=>`<li>${s[0]} ${s[1]}</li>`).join('')}</ol>`);setTimeout(()=>{if(!p.isConnected)return res();p.innerHTML='<p class="cp-q">🤫 The card is hidden. Remember the order!</p>';setTimeout(()=>{cpPanel('');res();},900);},ms);});}
function cpOrderTurns(steps,partner,partnerLine){return new Promise(res=>{let at=0,theirTurn=false,missed=false;const shuffled=zShuf(steps.map((s,i)=>[...s,i]));
 const p=cpPanel(`<div class="cp-volc" id="cpVolc"><div class="cp-cone">🌋</div><div class="cp-fill" id="cpFill"></div></div><p class="cp-q" id="cpTurn">Your turn: add step 1!</p><div class="cp-jobs">${shuffled.map(s=>`<button type="button" class="cp-job cp-ing" data-i="${s[2]}">${s[0]} ${s[1]}</button>`).join('')}</div>`);
 const T=$id('cpTurn');
 p.querySelectorAll('.cp-ing').forEach(b=>b.onclick=async()=>{if(theirTurn){if(!missed){missed=true;zMiss();}audio('tap');hoBounce(b);await cpSay(partner,'Wait! It’s my turn to measure.','think');return;}
  if(+b.dataset.i!==at){if(!missed){missed=true;zMiss();}audio('tap');hoBounce(b);T.textContent='Hmm, that’s not the next step. What was on the card?';return;}
  audio('good');b.classList.add('used');const f=$id('cpFill');if(f)f.style.height=((at+1)/steps.length*100)+'%';at++;
  if(at===steps.length){T.textContent='🌋 All mixed!';setTimeout(()=>res(!missed),500);return;}
  theirTurn=true;T.textContent=`⏳ ${CP_NAMES[partner]}’s turn to measure…`;await cpSay(partner,partnerLine[(at-1)%partnerLine.length]);if(!p.isConnected)return;theirTurn=false;T.textContent=`Your turn: add step ${at+1}!`;});});}
function cpBuildTurns(n,partner,label){return new Promise(res=>{let at=0,theirs=false,missed=false;const p=cpPanel(`<p class="cp-q" id="cpTurn">${label}</p><div class="cp-bridge"><span class="cp-bank l"></span><div class="cp-slots">${Array.from({length:n},(_,i)=>`<button type="button" class="cp-slot" data-i="${i}">${i%2?'':'⬜'}</button>`).join('')}</div><span class="cp-bank r"></span></div>`);
 const T=$id('cpTurn');const slots=[...p.querySelectorAll('.cp-slot')];const mark=()=>slots.forEach((s,i)=>s.classList.toggle('next',i===at&&!theirs));mark();
 slots.forEach(s=>s.onclick=async()=>{if(theirs){if(!missed){missed=true;zMiss();}audio('tap');hoBounce(s);await cpSay(partner,'Hey, it’s my turn!','think');return;}if(+s.dataset.i!==at)return;audio('good');s.classList.add('me');s.textContent='🧱';at++;mark();
  if(at>=n){setTimeout(()=>res(!missed),400);return;}theirs=true;mark();T.textContent=`⏳ ${CP_NAMES[partner]}’s turn…`;await cpWait(900);if(!p.isConnected)return;const z=slots[at];z.classList.add('them');z.textContent='🟪';audio('tap');at++;theirs=false;
  if(at>=n){setTimeout(()=>res(!missed),400);return;}T.textContent='Your turn! Add a block.';mark();});});}
function cpBreathe(times=2){return new Promise(res=>{let n=0;const p=cpPanel(`<p class="cp-q">😤 Riki feels frustrated. Take ${times} big balloon breaths first.</p><button type="button" class="ho-hold" id="cpBr">🎈 Hold to breathe in</button><small class="cp-tip" id="cpBn">0 of ${times}</small>`);const br=$id('cpBr');
 hoHold(br,1100,{label:s=>{br.firstChild.textContent=s==='out'?'😮‍💨 Let go to breathe out':'🎈 Keep holding…';},onDone:()=>{n++;audio('good');$id('cpBn').textContent=`${n} of ${times}`;br.firstChild.textContent='🎈 Hold to breathe in';if(n>=times){cpExpr('riki','happy');setTimeout(()=>{cpPanel('');res();},400);}}});});}
function cpShow(lines,partner){return new Promise(res=>{let at=0,missed=false,busy=false;const p=cpPanel(`<div class="cp-stage-mini"><div class="cp-curtain l"></div><div class="cp-curtain r"></div><span class="cp-pup a">🐉</span><span class="cp-pup b">👸</span></div><p class="cp-q" id="cpTurn"></p><button type="button" class="sl-big" id="cpMy">🎤 Say my line</button>`);
 const T=$id('cpTurn'),B=$id('cpMy');
 const step=async()=>{if(!p.isConnected)return;if(at>=lines.length){T.textContent='👏 The end!';B.hidden=true;setTimeout(()=>res(!missed),600);return;}const [who,txt]=lines[at];
  if(who==='riki'){T.textContent='🎤 Your turn! Say your line.';B.disabled=false;B.classList.add('go');}else{T.textContent=`🤫 ${CP_NAMES[who]}’s line. Listen…`;B.classList.remove('go');busy=true;await cpSay(who,txt);busy=false;at++;step();}};
 B.onclick=async()=>{if(busy){if(!missed){missed=true;zMiss();}audio('tap');hoBounce(B);await cpSay(partner,'Hey, you’re talking over me!','think');return;}const [who,txt]=lines[at]||[];if(who!=='riki')return;B.disabled=true;B.classList.remove('go');await cpSay('riki',txt);at++;step();};
 step();});}
Object.assign(CP_PROJECTS,{
 volcano:{name:'Science Volcano',ic:'🌋',partner:'luna',skill:'Follow steps in order, take turns, stay calm after a spill',run:async()=>{let stars=0;
  cpGoal('Go talk to Ms. Dana',['teacher']);
  await cpWaitTap({teacher:async()=>{await cpSay('teacher','Today you and Luna will make a volcano erupt! The recipe is on the board.');return true;}});
  cpGoal('Read the recipe on the board',['board']);
  await cpWaitTap({board:async()=>true,luna:async()=>{await cpSay('luna','Let’s read the recipe first!');return false;}});
  const steps=[['🥄','Baking soda'],['🔴','Red color'],['🫧','Dish soap'],['🧪','Vinegar']];await cpRecipe(steps,4200);
  cpGoal('Find Luna and decide who does what',['luna']);
  await cpWaitTap({luna:async()=>{await cpSay('luna','How should we split it?');const i=await cpAsk('What do you say to Luna?',[['“You measure, I pour. Then we switch!”'],['“I’ll do everything. You watch.”'],['“You do it all. I don’t care.”']]);
   if(i===0){stars++;await cpSay('luna','Deal! Great teamwork!','excited');return true;}zMiss();await cpSay('luna',i===1?'But I want to help too…':'Hmm… it’s more fun together.','sad');return false;}});
  await cpFetch([['soda','🥄','baking soda','shelf','Baking soda! 🥄'],['vin','🧪','vinegar','sink','Vinegar from by the sink! 🧪'],['color','🔴','red color','cubby','Red color! 🔴']]);
  cpGoal('Go back to the table and mix in order',['table']);await cpWaitTap({table:async()=>true,luna:async()=>true});
  cpGoal('Add the steps in order. Wait for Luna between turns!');
  if(await cpOrderTurns(steps,'luna',['Okay, I measured the next one!','Measured! Your turn.','All measured!']))stars++;
  await cpSay('luna','Oops! I spilled the vinegar everywhere!','surprised');cpExpr('luna','sad');
  cpGoal('Luna spilled! What will you do?',['luna','sink']);let kind=false;
  await cpWaitTap({sink:async()=>{await cpSay('riki','I got paper towels! Let’s clean it together.');kind=true;return true;},luna:async()=>{const i=await cpAsk('Luna looks upset.',[['“It’s okay, accidents happen! Let’s clean it.”'],['“You ruined our volcano!”']]);if(i===0){kind=true;return true;}zMiss();cpExpr('luna','sad');await cpSay('luna','I didn’t mean to…','sad');return false;}});
  if(kind)stars++;cpExpr('luna','happy');await cpSay('luna','Thanks, Riki. Let’s make it erupt!','excited');
  const p=cpPanel('<div class="cp-volc boom"><div class="cp-cone">🌋</div><div class="cp-lava"></div></div><p class="cp-q">💥 ERUPTION!</p>');audio('good');await cpWait(1800);
  cpGoal('Show Ms. Dana your volcano!',['teacher']);await cpWaitTap({teacher:async()=>true});return stars;}},
 bridge:{name:'Block Bridge',ic:'🌉',partner:'zoe',skill:'Build together, take turns, keep trying when it falls',run:async()=>{let stars=0;
  cpGoal('Go talk to Ms. Dana',['teacher']);
  await cpWaitTap({teacher:async()=>{await cpSay('teacher','You and Zoe will build a block bridge strong enough for the toy car!');return true;}});
  cpGoal('Find Zoe and plan the bridge',['zoe']);await cpWaitTap({zoe:async()=>{await cpSay('zoe','I want a tall tower on our bridge! What do you want?');return true;}});
  if(await cpMerge(['🌉 Long bridge'],['🗼 Tall tower','Zoe','zoe'],'🌉🗼 A long bridge with a tower!'))stars++;
  await cpSay('zoe','Yes! Let’s take turns adding blocks.','excited');
  await cpFetch([['blocks','🧱','blocks','cubby','Lots of blocks! 🧱'],['car','🚗','toy car','shelf','The toy car! 🚗']]);
  cpGoal('Go to the art table to build',['table']);await cpWaitTap({table:async()=>true,zoe:async()=>true});
  cpGoal('Take turns building with Zoe');let ok=await cpBuildTurns(6,'zoe','Your turn! Tap the glowing spot to add a block.');
  const p=cpPanel('<div class="cp-bridge fall"><span class="cp-bank l"></span><div class="cp-slots"><span>🧱</span><span>🟪</span><span>🧱</span><span>🟪</span></div><span class="cp-bank r"></span><span class="cp-car">🚗</span></div><p class="cp-q">💥 CRASH! The bridge fell down!</p>');await cpWait(1600);cpExpr('riki','upset');
  await cpBreathe(2);
  const i=await cpAsk('The bridge fell. What now?',[['“Let’s try again. Big blocks on the bottom!”'],['“This is stupid. I quit!”'],['“It’s YOUR fault, Zoe!”']]);
  if(i===0){stars+=ok?1:0;await cpSay('zoe','Good idea! Big ones on the bottom!','excited');}else{zMiss();await cpSay('zoe',i===1?'Don’t quit! We can fix it together.':'That’s not fair… we built it together.','sad');await cpSay('riki','You’re right. Let’s try again, big blocks on the bottom!');}
  cpGoal('Rebuild the bridge together');if(await cpBuildTurns(4,'zoe','Rebuild! Big blocks first.'))stars++;
  cpPanel('<div class="cp-bridge win"><span class="cp-bank l"></span><div class="cp-slots"><span>🧱</span><span>🟪</span><span>🧱</span><span>🟪</span></div><span class="cp-bank r"></span><span class="cp-car go">🚗</span></div><p class="cp-q">🎉 The car made it across!</p>');audio('good');await cpWait(1800);
  cpGoal('Show Ms. Dana your bridge!',['teacher']);await cpWaitTap({teacher:async()=>true});return stars;}},
 puppet:{name:'Puppet Show',ic:'🎭',partner:'ava',skill:'Take turns talking, work with a bossy friend, keep going',run:async()=>{let stars=0;
  cpGoal('Go talk to Ms. Dana',['teacher']);
  await cpWaitTap({teacher:async()=>{await cpSay('teacher','You and Ava will put on a puppet show for the class!');return true;}});
  cpGoal('Find Ava and plan the show',['ava']);
  await cpWaitTap({ava:async()=>{await cpSay('ava','I’ll be the princess AND the dragon AND tell the whole story!','excited');const i=await cpAsk('Ava wants to do everything. What do you say?',[['“Can we take turns? You be the princess, I’ll be the dragon.”'],['“You’re SO bossy!”'],['“Fine… you do everything.”']]);
   if(i===0){stars++;await cpSay('ava','Okay! That’s fair. You can be the dragon!','excited');return true;}zMiss();await cpSay('ava',i===1?'Hey, that’s mean…':'Wait, don’t you want a part too?','sad');return false;}});
  await cpFetch([['pup','🐉','dragon puppet','shelf','The dragon puppet! 🐉'],['cur','🎪','curtain','cubby','The curtain! 🎪']]);
  cpGoal('Go to the stage spot by the rug',['table']);await cpWaitTap({table:async()=>true,ava:async()=>true});
  cpGoal('Showtime! Only talk on your turn.');
  if(await cpShow([['ava','Once upon a time, a princess lived in a castle.'],['riki','Roar! I am a lonely dragon.'],['ava','Why are you lonely, dragon?'],['riki','Nobody wants to play with me.'],['ava','I will be your friend!'],['riki','Hooray! Let’s have a tea party!']],'ava'))stars++;
  cpExpr('lily','excited');await cpSay('lily','Hahaha! The dragon has a funny voice!','excited');
  cpGoal('Lily laughed. What will you do?',[]);const i=await cpAsk('Lily is laughing during the show.',[['Smile and keep going'],['“Stop laughing at us!”']]);
  if(i===0){stars++;await cpSay('riki','Roar! Thank you, thank you!');await cpSay('lily','That was so funny! I loved it!','excited');}else{zMiss();await cpSay('lily','Sorry… I was laughing because it was funny!','sad');}
  cpGoal('Take a bow and talk to Ms. Dana',['teacher']);await cpWaitTap({teacher:async()=>true});return stars;}}});
const cpDrawPrior=drawClassProjects;drawClassProjects=function(){cpDrawPrior();document.querySelectorAll('.cp-proj.soon').forEach(x=>x.remove());const pick=document.querySelector('.cp-pick');if(!pick)return;['volcano','bridge','puppet'].forEach(k=>{if(pick.querySelector(`[data-p="${k}"]`))return;const p=CP_PROJECTS[k];const b=document.createElement('button');b.type='button';b.className='cp-proj';b.dataset.p=k;b.innerHTML=`<b>${p.ic}</b><strong>${p.name}</strong><small>${p.skill}</small>${zSave.stars['cp_'+k]?`<i>⭐${zSave.stars['cp_'+k]}</i>`:''}`;b.onclick=()=>{audio('tap');cpStart(k);};pick.appendChild(b);});};
ZRUN.classproj=drawClassProjects;
if(!document.getElementById('cp3Css')){const st=document.createElement('style');st.id='cp3Css';st.textContent=`.cp-recipe{margin:0;padding:10px 10px 10px 34px;background:#fff;border-radius:16px;font-weight:900;font-size:16px;color:#4a2338;line-height:1.8}
.cp-volc{position:relative;height:120px;margin:0 auto;width:140px;display:grid;place-items:end center}.cp-cone{font-size:96px;line-height:1;position:relative;z-index:2}.cp-fill{position:absolute;bottom:10px;left:50%;width:30px;margin-left:-15px;height:0;background:linear-gradient(#ff7a59,#ff3d6e);border-radius:8px 8px 4px 4px;transition:height .4s cubic-bezier(0.23,1,0.32,1);z-index:1;opacity:.9}
.cp-volc.boom .cp-lava{position:absolute;left:50%;top:8px;width:20px;height:20px;margin-left:-10px;border-radius:50%;background:#ff4d4d;box-shadow:0 0 0 6px #ff9a3c,0 0 0 14px #ffd34d66;animation:cpBoom .9s ease-out infinite;z-index:3}@keyframes cpBoom{from{transform:translateY(10px) scale(.4);opacity:1}to{transform:translateY(-60px) scale(2.2);opacity:0}}
.cp-bridge{position:relative;display:flex;align-items:flex-end;justify-content:center;gap:0;height:110px;background:linear-gradient(transparent 70%,#8fd3ff 70%);border-radius:16px;overflow:hidden}.cp-bank{width:50px;height:70px;background:#9fdc7c;border-radius:10px 10px 0 0}.cp-slots{display:flex;align-items:flex-end;margin-bottom:40px}.cp-slots span,.cp-slot{font-size:28px;width:40px;height:40px;display:grid;place-items:center;border:0;background:none;padding:0}
.cp-slot{border:2px dashed #d9c9f5;border-radius:8px;background:#fff8;cursor:pointer;font-size:24px}.cp-slot.next{border-color:#ff7eb6;background:#ffe6f1;animation:cpPulse 1s ease-in-out infinite}@keyframes cpPulse{50%{transform:scale(1.12)}}.cp-slot.me,.cp-slot.them{border:0;background:none;font-size:30px;animation:hoIn 240ms cubic-bezier(0.23,1,0.32,1)}
.cp-car{position:absolute;left:4px;bottom:72px;font-size:28px}.cp-bridge.fall .cp-slots{animation:cpFall 1s ease-in .6s forwards}@keyframes cpFall{to{transform:translateY(60px) rotate(12deg);opacity:.4}}.cp-bridge.fall .cp-car{animation:cpDrive .7s ease-in forwards}.cp-car.go{animation:cpAcross 1.6s ease-in-out forwards}@keyframes cpDrive{to{left:40%}}@keyframes cpAcross{to{left:calc(100% - 40px)}}
.cp-stage-mini{position:relative;height:120px;border-radius:16px;background:linear-gradient(#ffe6f1,#ffd0e4);overflow:hidden;box-shadow:inset 0 -14px 0 #c9925a}.cp-curtain{position:absolute;top:0;bottom:14px;width:22%;background:repeating-linear-gradient(90deg,#e2385f 0 10px,#c42a4f 10px 20px)}.cp-curtain.l{left:0}.cp-curtain.r{right:0}.cp-pup{position:absolute;bottom:14px;font-size:54px;animation:cpPup 1.2s ease-in-out infinite}.cp-pup.a{left:28%}.cp-pup.b{right:28%;animation-delay:.6s}@keyframes cpPup{50%{transform:translateY(-8px) rotate(-4deg)}}
#cpMy.go{box-shadow:0 0 0 4px #ffd34d,0 6px 0 #c2185b}
@media (prefers-reduced-motion:reduce){.cp-pup,.cp-slot.next,.cp-volc.boom .cp-lava{animation:none}}`;document.head.appendChild(st);}

